//! The sync wire format, pinned byte for byte.
//!
//! Every message a peer sends is an encoded `SyncMessage`, and peers on
//! different app versions have to read each other. These fixtures were
//! encoded by bincode 1.3.3, the format's first and only definition, and
//! the encoder in use today has to produce exactly the same bytes and read
//! them back.

use chrono::{DateTime, TimeZone, Utc};
use uuid::Uuid;

use crate::protocol::{
    decode_message, encode_message, DeltaRef, EntityType, ManifestEntry, SyncMessage, SyncRecord,
};

fn id(n: u8) -> Uuid {
    Uuid::from_bytes([n, 0x11, 0x22, 0x33, 0x44, 0x55, 0x46, 0x77, 0x88, 0x99, 0xaa, 0xbb, 0xcc, 0xdd, 0xee, n])
}

/// One instant per precision chrono's serde form distinguishes: whole
/// seconds, milliseconds, microseconds and nanoseconds.
fn times() -> [DateTime<Utc>; 4] {
    let base = Utc.with_ymd_and_hms(2026, 10, 4, 12, 34, 56).unwrap();
    [
        base,
        base + chrono::Duration::milliseconds(120),
        base + chrono::Duration::microseconds(123_456),
        base + chrono::Duration::nanoseconds(123_456_789),
    ]
}

/// Every variant of the message, each field carrying a value that is not
/// its default, plus every `EntityType` and every time precision.
pub(crate) fn fixtures() -> Vec<SyncMessage> {
    let t = times();
    let manifest = EntityType::ALL
        .iter()
        .enumerate()
        .map(|(i, kind)| ManifestEntry {
            entity_type: *kind,
            entity_id: id(i as u8),
            updated_at: t[i % t.len()],
            is_deleted: i % 3 == 0,
        })
        .collect();
    let records = EntityType::ALL
        .iter()
        .enumerate()
        .map(|(i, kind)| SyncRecord {
            entity_type: *kind,
            entity_id: id(0x40 + i as u8),
            updated_at: t[(i + 1) % t.len()],
            is_deleted: i % 2 == 0,
            payload: (0..(i * 7) as u8).collect(),
        })
        .collect::<Vec<_>>();
    vec![
        SyncMessage::Hello { device_id: id(1), protocol_version: 8, auth_signature: vec![0xab; 64] },
        SyncMessage::HelloAck { device_id: id(2), protocol_version: 7, auth_signature: vec![1, 2, 3] },
        SyncMessage::PairingRequest {
            device_id: id(3),
            device_name: "Laptop da Ana, 漢字 ✓".into(),
            public_key: vec![0x5a; 32],
            pairing_code: "482-917".into(),
            listen_port: 51234,
            x25519_pub: vec![0x77; 32],
        },
        SyncMessage::PairingChallenge { challenge: vec![9; 32] },
        SyncMessage::PairingResponse { signed_challenge: vec![8; 64] },
        SyncMessage::PairingAccepted {
            device_id: id(4),
            device_name: String::new(),
            public_key: vec![0x33; 32],
            x25519_pub: vec![0x44; 32],
        },
        SyncMessage::PairingRejected { reason: "code expired".into() },
        SyncMessage::ManifestRequest,
        SyncMessage::Manifest { entries: manifest },
        SyncMessage::DeltaRequest {
            needed: EntityType::ALL
                .iter()
                .enumerate()
                .map(|(i, kind)| DeltaRef { entity_type: *kind, entity_id: id(0x80 + i as u8) })
                .collect(),
        },
        SyncMessage::DeltaResponse { records: records.clone() },
        SyncMessage::DeltaPush { records: records[..3].to_vec() },
        SyncMessage::DeltaAck { accepted: vec![id(5), id(6), id(7)] },
        SyncMessage::Ping,
        SyncMessage::Pong,
        SyncMessage::Bye,
        SyncMessage::RelayHello { device_id: id(8), protocol_version: 8, client_nonce: [0xc1; 32] },
        SyncMessage::RelayHelloAck {
            device_id: id(9),
            protocol_version: 8,
            server_nonce: core::array::from_fn(|i| i as u8),
            server_signature: vec![0xee; 64],
        },
        SyncMessage::RelayAuth { client_signature: vec![] },
    ]
}

/// The frames bincode 1.3.3 produced for [`fixtures`], hex, 4-byte length
/// header included.
const GOLDEN: &[&str] = &[
    "6800000000000000100000000000000001112233445546778899aabbccddee01080000004000000000000000abababababababababababababababababababababababababababababababababababababababababababababababababababababababababababababababab",
    "2b00000001000000100000000000000002112233445546778899aabbccddee02070000000300000000000000010203",
    "",
    "2c0000000300000020000000000000000909090909090909090909090909090909090909090909090909090909090909",
    "4c00000004000000400000000000000008080808080808080808080808080808080808080808080808080808080808080808080808080808080808080808080808080808080808080808080808080808",
    "7400000005000000100000000000000004112233445546778899aabbccddee0400000000000000002000000000000000333333333333333333333333333333333333333333333333333333333333333320000000000000004444444444444444444444444444444444444444444444444444444444444444",
    "18000000060000000c00000000000000636f64652065787069726564",
    "0400000007000000",
    "",
    "",
    "",
    "",
    "540000000c0000000300000000000000100000000000000005112233445546778899aabbccddee05100000000000000006112233445546778899aabbccddee06100000000000000007112233445546778899aabbccddee07",
    "040000000d000000",
    "040000000e000000",
    "040000000f000000",
    "4000000010000000100000000000000008112233445546778899aabbccddee0808000000c1c1c1c1c1c1c1c1c1c1c1c1c1c1c1c1c1c1c1c1c1c1c1c1c1c1c1c1c1c1c1c1",
    "8800000011000000100000000000000009112233445546778899aabbccddee0908000000000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f4000000000000000eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee",
    "0c000000120000000000000000000000",
];

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

#[test]
fn every_message_encodes_to_its_golden_bytes() {
    let fixtures = fixtures();
    assert_eq!(fixtures.len(), GOLDEN.len(), "one golden frame per fixture");
    for (i, (msg, gold)) in fixtures.iter().zip(GOLDEN).enumerate() {
        assert_eq!(&hex(&encode_message(msg).unwrap()), gold, "fixture {i} ({msg:?}) changed on the wire");
    }
}

#[test]
fn every_golden_frame_decodes_back_to_its_message() {
    for (i, (msg, gold)) in fixtures().iter().zip(GOLDEN).enumerate() {
        let frame: Vec<u8> = (0..gold.len()).step_by(2).map(|j| u8::from_str_radix(&gold[j..j + 2], 16).unwrap()).collect();
        let len = u32::from_le_bytes(frame[..4].try_into().unwrap()) as usize;
        assert_eq!(len, frame.len() - 4, "fixture {i}: header length");
        let decoded = decode_message(&frame[4..]).unwrap();
        // `SyncMessage` has no `PartialEq`; re-encoding compares every field.
        assert_eq!(hex(&encode_message(&decoded).unwrap()), *gold, "fixture {i} ({msg:?}) did not round-trip");
    }
}

#[test]
fn wire_time_is_the_string_chrono_serializes() {
    // The timestamp is written by hand (`WireTime`), so check it against
    // chrono's own serde output across every fraction length and both
    // sides of the epoch, not only the four golden instants.
    let base = Utc.with_ymd_and_hms(2026, 10, 4, 12, 34, 56).unwrap();
    let mut nanos = vec![0, 1, 10, 999, 1_000, 1_000_000, 100_000_000, 999_999_999];
    nanos.extend((0..200).map(|i: i64| i * 4_999_993));
    for base in [base, Utc.with_ymd_and_hms(1969, 12, 31, 23, 59, 59).unwrap()] {
        for n in &nanos {
            let t = base + chrono::Duration::nanoseconds(*n);
            let serde = serde_json::to_string(&t).unwrap();
            assert_eq!(format!("\"{}\"", crate::protocol::wire_time(&t)), serde, "{n} ns");
        }
    }
}
